const MAX_RECURSIVE_FAKE_SCHEDULER_RPC_STEPS: u32 = 10_000;
const MAX_RECURSIVE_LIVE_SCHEDULER_RPC_STEPS: u32 = 10_000;
const DEFAULT_RECURSIVE_LIVE_READ_LIMIT: u32 = 100;
const MAX_RECURSIVE_LIVE_READ_LIMIT: u32 = 500;
const RECURSIVE_ARTIFACT_SUMMARY_CURSOR_VERSION: u32 = 1;
const RECURSIVE_ARTIFACT_SUMMARY_CURSOR_ENDPOINT: &str = "ListRecursiveExecutionArtifactSummaries";
const RECURSIVE_ARTIFACT_SUMMARY_CURSOR_SORT: &str = "created_at_desc_id_desc";

fn decode_issue_workspace_params<T: DeserializeOwned>(request: &RpcRequest) -> Result<T> {
    serde_json::from_value(request.params.clone()).map_err(|_| {
        issue_workspace_error(IssueWorkspaceErrorCodeV1::InvalidRequest, None, None, None)
    })
}

fn normalize_issue_workspace_failure(error: DaemonError) -> DaemonError {
    if matches!(error, DaemonError::StructuredRpc { .. }) {
        return error;
    }
    tracing::error!(error = %error, "Issue workspace RPC failed internally");
    DaemonError::Rpc("Issue workspace operation failed".to_string())
}

pub(crate) fn link_issue_rpc_error(error: &IdeaControlError) -> DaemonError {
    let (rpc_code, code, message, details) = match error {
        IdeaControlError::InvalidRequest(_) => (
            INVALID_PARAMS,
            "ISSUE_LINK_INVALID_REQUEST",
            "invalid Issue link request",
            serde_json::Value::Null,
        ),
        IdeaControlError::IssueNotFound => (
            INVALID_PARAMS,
            "ISSUE_NOT_FOUND",
            "Issue not found",
            serde_json::Value::Null,
        ),
        IdeaControlError::IdeaNotFound => (
            INVALID_PARAMS,
            "IDEA_NOT_FOUND",
            "Idea not found",
            serde_json::Value::Null,
        ),
        IdeaControlError::ProjectScopeMismatch => (
            INVALID_PARAMS,
            "ISSUE_LINK_PROJECT_SCOPE_MISMATCH",
            "Issue link project scope mismatch",
            serde_json::Value::Null,
        ),
        IdeaControlError::SourceEventScopeMismatch => (
            INVALID_PARAMS,
            "ISSUE_LINK_SOURCE_EVENT_MISMATCH",
            "Issue link source event mismatch",
            serde_json::Value::Null,
        ),
        IdeaControlError::IssueAlreadyLinked => (
            INVALID_PARAMS,
            "ISSUE_ALREADY_LINKED",
            "Issue is already linked",
            serde_json::Value::Null,
        ),
        IdeaControlError::StaleVersion { expected, actual } => (
            INVALID_PARAMS,
            "ISSUE_LINK_STALE_IDEA_VERSION",
            "stale Idea row version",
            serde_json::json!({"expected": expected, "actual": actual}),
        ),
        IdeaControlError::IdempotencyConflict => (
            INVALID_PARAMS,
            "ISSUE_LINK_IDEMPOTENCY_CONFLICT",
            "Issue link idempotency conflict",
            serde_json::Value::Null,
        ),
        IdeaControlError::Contention => (
            INTERNAL_ERROR,
            "ISSUE_LINK_CONTENTION",
            "Issue link storage contention",
            serde_json::json!({"retryable": true}),
        ),
        IdeaControlError::ConstraintViolation { class } => (
            INTERNAL_ERROR,
            "ISSUE_LINK_CONSTRAINT_FAILURE",
            "Issue link integrity constraint failed",
            serde_json::json!({"class": class.as_str()}),
        ),
        IdeaControlError::CorruptStoredIssueLink => (
            INTERNAL_ERROR,
            "ISSUE_LINK_CORRUPT_STATE",
            "Issue link stored state is corrupt",
            serde_json::Value::Null,
        ),
        IdeaControlError::StorageFailure(_) => (
            INTERNAL_ERROR,
            "ISSUE_LINK_STORAGE_FAILURE",
            "Issue link storage failure",
            serde_json::Value::Null,
        ),
        _ => (
            INTERNAL_ERROR,
            "ISSUE_LINK_STORAGE_FAILURE",
            "Issue link storage failure",
            serde_json::Value::Null,
        ),
    };
    DaemonError::StructuredRpc {
        rpc_code,
        message: message.to_string(),
        data: serde_json::json!({"code": code, "details": details}),
    }
}

#[allow(clippy::too_many_lines)]
pub(crate) fn program_run_rpc_error(error: &ProgramRunControlError) -> DaemonError {
    let (rpc_code, code, message, retryable) = match error {
        ProgramRunControlError::InvalidRequest => (
            INVALID_PARAMS,
            "PROGRAM_RUN_INVALID_REQUEST",
            "invalid ProgramRun request",
            false,
        ),
        ProgramRunControlError::Forbidden => (
            INVALID_PARAMS,
            "PROGRAM_RUN_FORBIDDEN",
            "ProgramRun operation is forbidden",
            false,
        ),
        ProgramRunControlError::NotFound => (
            INVALID_PARAMS,
            "PROGRAM_RUN_NOT_FOUND",
            "ProgramRun not found",
            false,
        ),
        ProgramRunControlError::ActiveRunExists => (
            INVALID_PARAMS,
            "PROGRAM_RUN_ACTIVE_EXISTS",
            "an active ProgramRun already exists",
            false,
        ),
        ProgramRunControlError::ReplayConflict => (
            INVALID_PARAMS,
            "PROGRAM_RUN_REPLAY_CONFLICT",
            "ProgramRun idempotency replay conflict",
            false,
        ),
        ProgramRunControlError::StaleRunVersion => (
            INVALID_PARAMS,
            "PROGRAM_RUN_STALE_VERSION",
            "stale ProgramRun version",
            true,
        ),
        ProgramRunControlError::StaleIdeaVersion => (
            INVALID_PARAMS,
            "PROGRAM_RUN_STALE_IDEA_VERSION",
            "stale Idea version",
            true,
        ),
        ProgramRunControlError::StaleControllerEpoch
        | ProgramRunControlError::ControllerMismatch => (
            INVALID_PARAMS,
            "PROGRAM_RUN_STALE_AUTHORITY",
            "ProgramRun authority is stale",
            false,
        ),
        ProgramRunControlError::StaleLeaseGeneration
        | ProgramRunControlError::StaleClaimGeneration => (
            INVALID_PARAMS,
            "PROGRAM_RUN_STALE_GENERATION",
            "ProgramRun generation is stale",
            true,
        ),
        ProgramRunControlError::InvalidTransition
        | ProgramRunControlError::CursorInvariant
        | ProgramRunControlError::GateIncomplete
        | ProgramRunControlError::TerminalRun => (
            INVALID_PARAMS,
            "PROGRAM_RUN_INVALID_TRANSITION",
            "ProgramRun transition is not permitted",
            false,
        ),
        ProgramRunControlError::BudgetExhausted => (
            INVALID_PARAMS,
            "PROGRAM_RUN_BUDGET_EXHAUSTED",
            "ProgramRun budget is exhausted",
            false,
        ),
        ProgramRunControlError::QueueBackpressure => (
            INVALID_PARAMS,
            "PROGRAM_RUN_QUEUE_BACKPRESSURE",
            "ProgramRun queue is full",
            true,
        ),
        ProgramRunControlError::LockUnavailable => (
            INVALID_PARAMS,
            "PROGRAM_RUN_LOCK_UNAVAILABLE",
            "ProgramRun lock is unavailable",
            true,
        ),
        ProgramRunControlError::Quarantined | ProgramRunControlError::DownstreamReplayConflict => (
            INVALID_PARAMS,
            "PROGRAM_RUN_QUARANTINED",
            "ProgramRun requires operator reconciliation",
            false,
        ),
        ProgramRunControlError::Contention => (
            INTERNAL_ERROR,
            "PROGRAM_RUN_CONTENTION",
            "ProgramRun storage contention",
            true,
        ),
        ProgramRunControlError::ConstraintViolation
        | ProgramRunControlError::CorruptStoredState
        | ProgramRunControlError::StorageFailure => (
            INTERNAL_ERROR,
            "PROGRAM_RUN_STORAGE_FAILURE",
            "ProgramRun storage failure",
            false,
        ),
    };
    DaemonError::StructuredRpc {
        rpc_code,
        message: message.into(),
        data: serde_json::json!({"code": code, "details": {"retryable": retryable}}),
    }
}

fn validate_recursive_rpc_nonempty(label: &str, value: &str) -> Result<()> {
    if value.trim().is_empty() {
        Err(DaemonError::InvalidParam(format!(
            "Invalid params: {label} must not be empty"
        )))
    } else {
        Ok(())
    }
}

fn validate_recursive_rpc_optional_nonempty(label: &str, value: Option<&str>) -> Result<()> {
    if let Some(value) = value {
        validate_recursive_rpc_nonempty(label, value)?;
    }
    Ok(())
}

fn topology_recovery_rpc_error(error: DaemonError) -> DaemonError {
    match error {
        DaemonError::Store(message) => DaemonError::InvalidParam(message),
        DaemonError::InvalidParam(message) => DaemonError::InvalidParam(message),
        other => other,
    }
}

fn bounded_recursive_live_read_limit(limit: Option<u32>) -> Result<u32> {
    match limit {
        Some(0) => Err(DaemonError::InvalidParam(
            "Invalid params: limit must be positive".to_string(),
        )),
        Some(value) => Ok(value.min(MAX_RECURSIVE_LIVE_READ_LIMIT)),
        None => Ok(DEFAULT_RECURSIVE_LIVE_READ_LIMIT),
    }
}

fn recursive_live_output_not_ready_message(
    live_attempt_id: rsi_common::RecursiveLiveAttemptId,
    reason: RecursiveDagLiveOutputNotReadyReason,
) -> String {
    match reason {
        RecursiveDagLiveOutputNotReadyReason::LiveAttemptMissingSession => {
            format!("recursive live attempt {live_attempt_id} has no attached session")
        }
        RecursiveDagLiveOutputNotReadyReason::SessionNotFound => {
            format!("recursive live attempt {live_attempt_id} attached session was not found")
        }
        RecursiveDagLiveOutputNotReadyReason::SessionNotCompleted => {
            format!("recursive live attempt {live_attempt_id} attached session is not Completed")
        }
    }
}

fn validate_recursive_live_scheduler_params(
    params: &RunRecursiveLiveSchedulerParams,
) -> Result<()> {
    if params.max_steps == 0 {
        return Err(DaemonError::InvalidParam(
            "Invalid params: max_steps must be positive".to_string(),
        ));
    }
    if params.max_steps > MAX_RECURSIVE_LIVE_SCHEDULER_RPC_STEPS {
        return Err(DaemonError::InvalidParam(format!(
            "Invalid params: max_steps must be <= {MAX_RECURSIVE_LIVE_SCHEDULER_RPC_STEPS}"
        )));
    }
    validate_recursive_rpc_optional_nonempty("operator", params.operator.as_deref())?;
    validate_recursive_rpc_optional_nonempty("idempotency_key", params.idempotency_key.as_deref())?;
    validate_recursive_rpc_optional_nonempty("model", params.model.as_deref())?;
    validate_recursive_rpc_optional_nonempty("effort", params.effort.as_deref())?;
    validate_recursive_rpc_optional_nonempty("approval_mode", params.approval_mode.as_deref())?;
    if params.heartbeat_ttl_ms.is_some() {
        return Err(DaemonError::InvalidParam(
            "Invalid params: heartbeat_ttl_ms is not supported because the recursive DAG live scheduler heartbeat loop is disabled".to_string(),
        ));
    }
    if params.output_repair_attempts.unwrap_or(0) != 0 {
        return Err(DaemonError::InvalidParam(
            "Invalid params: output_repair_attempts must be 0 because live output repair is not wired into the request-scoped scheduler".to_string(),
        ));
    }
    if let Some(policy) = &params.tool_policy {
        for tool in policy
            .allowed_tools
            .iter()
            .chain(policy.denied_tools.iter())
        {
            validate_recursive_rpc_nonempty("tool_policy tool", tool)?;
        }
    }
    if let Some(policy) = &params.sandbox_policy {
        validate_recursive_rpc_optional_nonempty(
            "sandbox_policy.requested_branch",
            policy.requested_branch.as_deref(),
        )?;
    }
    Ok(())
}

fn recursive_live_scheduler_request_fingerprint(
    params: &RunRecursiveLiveSchedulerParams,
) -> Result<String> {
    let value = serde_json::to_value(params)?;
    Ok(format!(
        "{:x}",
        Sha256::digest(value.to_string().as_bytes())
    ))
}

fn recursive_live_scheduler_policy_snapshot(
    params: &RunRecursiveLiveSchedulerParams,
) -> Result<serde_json::Value> {
    Ok(serde_json::json!({
        "gate": "recursive_dag_live_scheduler_control_enabled",
        "reachability": "explicit_manual_rpc",
        "execution_path": "ordinary_recursive_dag_live_scheduler",
        "topology_live_scheduler": false,
        "background_loop_enabled": false,
        "heartbeat_loop_enabled": false,
        "output_repair_attempts": params.output_repair_attempts.unwrap_or(0),
        "request": serde_json::to_value(params)?,
    }))
}

fn recursive_live_tool_policy(
    policy: Option<&rsi_common::RecursiveLiveToolPolicy>,
) -> RecursiveDagLiveToolPolicy {
    RecursiveDagLiveToolPolicy {
        allowed_tools: policy
            .map(|policy| policy.allowed_tools.clone())
            .unwrap_or_default(),
        denied_tools: policy
            .map(|policy| policy.denied_tools.clone())
            .unwrap_or_default(),
    }
}

fn recursive_live_sandbox_policy(
    policy: Option<&rsi_common::RecursiveLiveSandboxPolicy>,
    sandbox: Option<&rsi_common::types::SandboxSpec>,
) -> RecursiveDagLiveSandboxPolicy {
    RecursiveDagLiveSandboxPolicy {
        requested_kind: policy
            .and_then(|policy| policy.requested_kind)
            .or_else(|| sandbox.and_then(|sandbox| sandbox.kind)),
        requested_branch: policy
            .and_then(|policy| policy.requested_branch.clone())
            .or_else(|| sandbox.and_then(|sandbox| sandbox.branch.clone())),
        preserve_on_failure: policy.and_then(|policy| policy.preserve_on_failure),
        allowed_write_roots: policy
            .map(|policy| policy.allowed_write_roots.clone())
            .unwrap_or_default(),
    }
}

fn structured_rpc_error(
    rpc_code: i32,
    data_code: impl Into<String>,
    message: impl Into<String>,
    resource_type: Option<&str>,
    resource_id: Option<String>,
    details: Option<serde_json::Value>,
) -> DaemonError {
    let data = RpcErrorData {
        code: data_code.into(),
        resource_type: resource_type.map(str::to_string),
        resource_id,
        retryable: false,
        details,
    };
    DaemonError::StructuredRpc {
        rpc_code,
        message: message.into(),
        data: serde_json::to_value(data).unwrap_or_else(|_| serde_json::json!({})),
    }
}

fn structured_invalid_params(
    data_code: impl Into<String>,
    message: impl Into<String>,
    resource_type: Option<&str>,
    resource_id: Option<String>,
    details: Option<serde_json::Value>,
) -> DaemonError {
    structured_rpc_error(
        INVALID_PARAMS,
        data_code,
        message,
        resource_type,
        resource_id,
        details,
    )
}

fn recursive_graph_not_found_error(graph_id: RecursiveTaskGraphId) -> DaemonError {
    structured_invalid_params(
        "RECURSIVE_GRAPH_NOT_FOUND",
        format!("recursive DAG graph not found: {graph_id}"),
        Some("recursive_task_graph"),
        Some(graph_id.to_string()),
        None,
    )
}

fn bounded_recursive_read_page_limit(limit: Option<u32>) -> Result<u32> {
    match limit {
        Some(0) => Err(DaemonError::InvalidParam(
            "Invalid params: limit must be positive".to_string(),
        )),
        Some(value) => Ok(value.min(crate::store::recursive_dag::MAX_RECURSIVE_READ_PAGE_LIMIT)),
        None => Ok(crate::store::recursive_dag::DEFAULT_RECURSIVE_READ_PAGE_LIMIT),
    }
}

#[derive(Debug, Serialize)]
struct RecursiveArtifactSummaryCursorFilter {
    endpoint: &'static str,
    graph_id: String,
    task_id: Option<String>,
    attempt_id: Option<String>,
    kind: Option<&'static str>,
}

#[derive(Debug, Serialize, Deserialize)]
struct RecursiveArtifactSummaryCursorToken {
    version: u32,
    endpoint: String,
    sort: String,
    filter_hash: String,
    created_at: DateTime<Utc>,
    artifact_id: i64,
}

fn recursive_artifact_kind_wire(kind: RecursiveExecutionArtifactKind) -> &'static str {
    match kind {
        RecursiveExecutionArtifactKind::Inline => "inline",
        RecursiveExecutionArtifactKind::File => "file",
        RecursiveExecutionArtifactKind::SessionEvent => "session_event",
        RecursiveExecutionArtifactKind::WorkflowExecution => "workflow_execution",
    }
}

fn recursive_artifact_summary_cursor_filter(
    graph_id: RecursiveTaskGraphId,
    task_id: Option<RecursiveTaskId>,
    attempt_id: Option<RecursiveAttemptId>,
    kind: Option<RecursiveExecutionArtifactKind>,
) -> RecursiveArtifactSummaryCursorFilter {
    RecursiveArtifactSummaryCursorFilter {
        endpoint: RECURSIVE_ARTIFACT_SUMMARY_CURSOR_ENDPOINT,
        graph_id: graph_id.to_string(),
        task_id: task_id.map(|id| id.to_string()),
        attempt_id: attempt_id.map(|id| id.to_string()),
        kind: kind.map(recursive_artifact_kind_wire),
    }
}

fn recursive_artifact_summary_filter_hash(
    filter: &RecursiveArtifactSummaryCursorFilter,
) -> Result<String> {
    let bytes = serde_json::to_vec(filter).map_err(DaemonError::Json)?;
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    Ok(format!("sha256:{}", hex::encode(hasher.finalize())))
}

fn decode_recursive_artifact_summary_cursor(
    cursor: &str,
    expected_hash: &str,
) -> Result<crate::store::recursive_dag::RecursiveExecutionArtifactSummaryPageCursor> {
    let token: RecursiveArtifactSummaryCursorToken =
        serde_json::from_str(cursor).map_err(|error| {
            structured_invalid_params(
                "RECURSIVE_CURSOR_INVALID",
                format!("recursive artifact summary cursor is malformed: {error}"),
                Some("recursive_execution_artifact_summary_cursor"),
                None,
                None,
            )
        })?;
    if token.version != RECURSIVE_ARTIFACT_SUMMARY_CURSOR_VERSION
        || token.endpoint != RECURSIVE_ARTIFACT_SUMMARY_CURSOR_ENDPOINT
        || token.sort != RECURSIVE_ARTIFACT_SUMMARY_CURSOR_SORT
        || token.filter_hash != expected_hash
    {
        return Err(structured_invalid_params(
            "RECURSIVE_CURSOR_INVALID",
            "recursive artifact summary cursor does not match this request scope",
            Some("recursive_execution_artifact_summary_cursor"),
            None,
            Some(serde_json::json!({
                "cursor_version": token.version,
                "cursor_endpoint": token.endpoint,
                "cursor_sort": token.sort,
            })),
        ));
    }
    Ok(
        crate::store::recursive_dag::RecursiveExecutionArtifactSummaryPageCursor {
            created_at: token.created_at,
            artifact_id: token.artifact_id,
        },
    )
}

fn encode_recursive_artifact_summary_cursor(
    item: &RecursiveExecutionArtifactSummary,
    filter_hash: String,
) -> Result<String> {
    let token = RecursiveArtifactSummaryCursorToken {
        version: RECURSIVE_ARTIFACT_SUMMARY_CURSOR_VERSION,
        endpoint: RECURSIVE_ARTIFACT_SUMMARY_CURSOR_ENDPOINT.to_string(),
        sort: RECURSIVE_ARTIFACT_SUMMARY_CURSOR_SORT.to_string(),
        filter_hash,
        created_at: item.created_at,
        artifact_id: item.artifact_id,
    };
    serde_json::to_string(&token).map_err(DaemonError::Json)
}

fn redact_recursive_live_heartbeat_token(
    mut state: RecursiveLiveAttemptHeartbeatState,
) -> RecursiveLiveAttemptHeartbeatState {
    state.heartbeat_token = None;
    state
}

// ─── P0 session-attribution gate ────────────────────────────────────────
//
// Threat model (design doc `2026-06-30-agent-harness-control-via-rpc-cli.md`,
// "Threat model"): the socket is trust-by-ownership, so method-name
// allowlisting is not a security boundary against a malicious local
// process — any process running as the user can already open the socket
// unattributed. This gate is a correctness guard against a *confused*
// agent that follows the documented `rsi-rpc` + `$RSI_SESSION_TOKEN`
// contract: a call that carries a session token is classified as an
// *agent* call and is default-denied except for a closed, explicitly
// enumerated allowlist. A call with no token (TUI/operator/scripts) is
// completely unaffected — full surface, unchanged, exactly as today.
//
// Closed allowlist, NOT prefix matching (`Get*`/`List*` would silently
// admit a future `Get`-named mutation). Every entry here was reviewed and
// confirmed side-effect-free from the calling session's perspective, or is
// an `Agent*` verb that internally enforces its own self/lead scoping.
mod agent_gate {
    use std::collections::HashSet;
    use std::sync::LazyLock;

    /// `Agent*` verbs — tokened wrappers that internally enforce self/lead
    /// scoping via `SessionManager`/`SpawnCoordinator`, or (for
    /// `AgentScheduleWake`) bind their WAKE target exclusively to the
    /// resolved caller session, never to an agent-supplied id. The optional
    /// `watch_session_id` (A8 `mode:"on_terminal"`) names a watched SUBJECT,
    /// scoped exactly like `AgentGetStatus` targets (self / direct child /
    /// child-of-led-Epic, self-watch rejected) — it cannot steer the wake.
    pub(super) const AGENT_VERBS: &[&str] = &[
        "AgentSpawnChild",
        "AgentReserveSuccessor",
        "AgentGetProgress",
        "AgentSendMessage",
        "AgentGetStatus",
        "AgentHalt",
        "AgentContinueChild",
        "AgentArchiveChild",
        "AgentScheduleWake",
        "AgentCreateIssue",
        "AgentListIssues",
        "AgentGetIssue",
        "AgentUpdateIssue",
        "AgentUpdateIssueStatus",
        "AgentArchiveIssue",
        "AgentRestoreIssue",
        "AgentListIssueEvents",
        "AgentManagerProgress",
        "AgentManagerInbox",
        "AgentManagerSend",
        "AgentManagerReply",
        "AgentManagerNotify",
        "AgentManagerInspect",
        "AgentManagerUpdate",
        "AgentSubmitReviewReceipt",
        "AgentManagerControl",
        "AgentManagerPrepareControl",
        "AgentManagerCommitPreparedControl",
        "AgentManagerGetAction",
        "AgentManagerWorkView",
    ];

    /// Enumerated read-only verbs safe for an attributed (agent) caller.
    /// Deliberately small — extend by adding a name here after review, never
    /// by widening to a prefix match.
    pub(super) const READ_VERBS: &[&str] = &[
        "GetSession",
        "GetSessionSummary",
        "GetHealthStatus",
        "GetDaemonCapabilities",
        "ListSessionChildren",
        "GetConversation",
        "GetSessionDiagnostics",
        "GetConversationsSince",
        "GetTurnMetrics",
    ];

    /// The only `READ_VERBS` that name no target session. Every other read
    /// verb resolves the token caller and admits a target only inside its
    /// read scope (#241; `Store::agent_read_scope_admits`), refusing with
    /// `agent_read_scope_denied`.
    /// Pinned by the #241 coverage test so a new read verb cannot land
    /// without either scoping or an explicit entry here.
    #[cfg_attr(not(test), allow(dead_code))]
    pub(super) const UNSCOPED_READ_VERBS: &[&str] = &["GetHealthStatus", "GetDaemonCapabilities"];

    static ALLOWED: LazyLock<HashSet<&'static str>> = LazyLock::new(|| {
        AGENT_VERBS
            .iter()
            .chain(READ_VERBS.iter())
            .copied()
            .collect()
    });

    /// True if `method` may be called by a session-attributed (tokened)
    /// caller. Unattributed callers bypass this check entirely.
    pub(super) fn is_allowed_for_attributed_caller(method: &str) -> bool {
        ALLOWED.contains(method)
    }
}

/// Result of handling an RPC request. Normal returns a response to send.
/// Subscribe signals the connection should transition to push streaming mode.
enum HandleResult {
    Response(RpcResponse),
    Subscribe {
        response: RpcResponse,
        params: SubscribeParams,
    },
}

