        let deferred = tokio::task::spawn_blocking(move || {
            let store = store.blocking_lock();
            store.list_deferred_recursive_recovery_graphs()
        })
        .await
        .map_err(|e| DaemonError::Process(format!("Task join error: {}", e)))??;
