    // ─── Local issue tracker (Track C slice C3): operator-only RPC ──────
    //
    // Mirrors the Label family's handler shape exactly (deser -> Invalid
    // params via `DaemonError::Rpc`; store call via
    // `self.session_manager.store().lock().await`; `to_value` envelope).
    // No production store method is new here (C1 `store/issues.rs` already
    // has the whole surface) — these handlers are thin RPC adapters only.

    /// CreateIssue — operator-created issue; `created_by_session_id` is
    /// always `None` here (agent-attributed creation is C5, never this
    /// verb — P-001/P-003).
    async fn handle_create_issue(&self, request: &RpcRequest) -> Result<serde_json::Value> {
        let params: CreateIssueParams = serde_json::from_value(request.params.clone())
            .map_err(|e| DaemonError::Rpc(format!("Invalid params: {}", e)))?;
        let new = rsi_common::types::NewIssue {
            project_id: params.project_id,
            title: params.title,
            body: params.body,
            priority: params.priority,
            labels: params.labels,
            created_by_session_id: None,
            assignee: params.assignee,
            idea_id: None,
            source_event_id: None,
            source_finding_ref: None,
        };
        let store = self.session_manager.store().lock().await;
        let issue = store.create_issue(&new)?;
        Ok(serde_json::to_value(&issue)?)
    }

